        {
          "day": 2,
          "date": "2026-09-07",
          "risk_level": "unknown",
          "notes": "漓江精华游船为当天核心活动，天气或河道状况会影响游船运营，出行前需确认船班与退改政策。"
        },
        {
          "day": 3,
          "date": "2026-09-08",
          "risk_level": "unknown",
          "notes": "阳朔西街为夜间活动雨天影响较小，但白天户外观光（如七星景区）受天气影响，建议灵活调整。"
        }
      ],
      "adjustment_required": true
    },
    "itinerary": {
      "daily_itinerary": [
        {
          "day": 1,
          "attraction_poi_ids": [
            "gl002",
